sys_variable_value.value:
(function execute(inputs, outputs) {

    outputs.recommended_assignee = '';
    outputs.assignment_score = 0;


    var record = inputs.current_record;
    var task = new GlideRecord(record.getTableName().toString());
    task.get(record.sys_id);
    
    var scorer = new AssignmentScorer();
    var best = scorer.findBestAssignee(task);

        if (best && best.user) {
            task.assigned_to = best.user;
            task.recommended_assignee = best.user;
            task.assignment_score = best.score;
            task.model_version = 'flow_v1';
            task.update();

        outputs.recommended_assignee = best.user;
        outputs.assignment_score = best.score || 0;

        var usr = new GlideRecord('sys_user');
        usr.get(best.user);
        outputs.recommended_assignee_name = usr.name;

        gs.info('Assigned to27 ' + best.user + ' with score ' + best.score);
    } else {
        gs.info('No suitable assignee found for record ' + task.number);
    }

})(inputs, outputs);

